-- =============================================
-- Travery Backend - Seed Hotel Entities (V16)
-- Amenities, RoomTypes, Rooms, HotelServices,
-- Hotel-Amenity joins, RoomType-Amenity joins,
-- Hotel updates (description, check-in/out, refund policy)
-- =============================================
-- =============================================
-- ALTER TABLES (Missing columns from entity changes)
-- =============================================
-- 1. Add missing columns
ALTER TABLE add_on_orders 
    ADD COLUMN scheduled_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP;

ALTER TABLE hotel_bookings 
    ADD COLUMN actual_check_in_time timestamp(6),
    ADD COLUMN actual_check_out_time timestamp(6);

ALTER TABLE room_types 
    ADD COLUMN area INT NOT NULL DEFAULT 0,
    ADD COLUMN quantity INT NOT NULL DEFAULT 1;

ALTER TABLE rooms 
    ADD COLUMN floor INT NOT NULL DEFAULT 1;

-- 2. Drop extraneous columns not present in entities
ALTER TABLE hotel_services 
    DROP COLUMN is_active;

-- 3. Fix type and naming mismatches (star_rating -> average_rating)
ALTER TABLE hotels 
    DROP COLUMN star_rating,
    DROP COLUMN latitude,
    DROP COLUMN longitude,
    ADD COLUMN average_rating integer DEFAULT 0;

-- 4. Add missing foreign key constraints
ALTER TABLE routes 
    ADD CONSTRAINT fk_routes_refund_policy 
    FOREIGN KEY (refund_policy_id) REFERENCES refund_policies(id);

ALTER TABLE hotels 
    ADD CONSTRAINT fk_hotels_refund_policy 
    FOREIGN KEY (refund_policy_id) REFERENCES refund_policies(id);

ALTER TABLE chat_sessions 
    ADD CONSTRAINT fk_chat_sessions_tour_instance 
    FOREIGN KEY (tour_instance_id) REFERENCES tour_instances(id);


